const CATEGORY_DEFS = [['','no_category','cat_help_none'],['work','cat_work','cat_help_work'],['personal','cat_personal','cat_help_personal'],['followup','cat_followup','cat_help_followup'],['money','cat_money','cat_help_money'],['subscription','cat_subscription','cat_help_subscription'],['admin','cat_admin','cat_help_admin'],['health','cat_health','cat_help_health'],['family','cat_family','cat_help_family'],['home','cat_home','cat_help_home'],['idea','cat_idea','cat_help_idea'],['learning','cat_learning','cat_help_learning'],['travel','cat_travel','cat_help_travel'],['shopping','cat_shopping','cat_help_shopping'],['event','cat_event','cat_help_event'],['other','cat_other','cat_help_other']];
const RECURRENCE_DEFS = [['once','once','rec_help_once'],['daily','daily','rec_help_daily'],['weekdays','weekdays','rec_help_weekdays'],['weekly','weekly','rec_help_weekly'],['biweekly','biweekly','rec_help_biweekly'],['monthly','monthly','rec_help_monthly'],['bimonthly','bimonthly','rec_help_bimonthly'],['quarterly','quarterly','rec_help_quarterly'],['semiannual','semiannual','rec_help_semiannual'],['yearly','yearly','rec_help_yearly'],['custom_days','custom_days','rec_help_custom']];

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const state = {locale:getInitialLocale(),token:localStorage.getItem('resurface_token'),authMode:'signup',settings:null,config:{currencies:{},push:{configured:false,publicKey:null}},items:{today:[],upcoming:[],done:[]},selectedDays:7,isPremium:false,snoozeId:null,editId:null,detailItem:null,pendingResurfaceId:null,installPrompt:null,swRegistration:null,pushStatus:null};
const tr = key => I18N[state.locale]?.[key] ?? I18N.en[key] ?? key;

function getInitialLocale(){const saved=localStorage.getItem('resurface_locale');if(SUPPORTED_LOCALES.includes(saved))return saved;const lang=(navigator.languages?.[0]||navigator.language||'fr').slice(0,2).toLowerCase();return SUPPORTED_LOCALES.includes(lang)?lang:'fr'}
function deviceTimezone(){try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}catch{return'UTC'}}
function detectedCountry(){const lang=navigator.languages?.[0]||navigator.language||'';const region=lang.match(/[-_]([A-Za-z]{2})\b/)?.[1]?.toUpperCase();if(region)return region;const map={'America/New_York':'US','America/Chicago':'US','America/Denver':'US','America/Los_Angeles':'US','America/Sao_Paulo':'BR','America/Fortaleza':'BR','America/Manaus':'BR','Europe/Paris':'FR','Europe/London':'GB','America/Toronto':'CA','America/Vancouver':'CA','Africa/Porto-Novo':'BJ','Africa/Cotonou':'BJ','Europe/Madrid':'ES','Europe/Lisbon':'PT'};return map[deviceTimezone()]||null}
function currencyForCountry(country){return COUNTRY_CURRENCY[country]||'EUR'}
function currentCurrency(){return state.settings?.currency||currencyForCountry(state.settings?.country||detectedCountry())}
function localDateKey(date=new Date(),timeZone=state.settings?.timezone||deviceTimezone()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const p=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return`${p.year}-${p.month}-${p.day}`}
function addDays(key,days){const d=new Date(`${key}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(days));return d.toISOString().slice(0,10)}
function formatDateTime(item){const due=new Date(item.resurfaceAtUtc||`${item.resurfaceAt}T09:00:00Z`);return new Intl.DateTimeFormat(state.locale,{timeZone:state.settings?.timezone||deviceTimezone(),day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(due)}
function formatPrice(code){const amount=state.config.currencies?.[code]?.amount??FALLBACK_PRICES[code]??9;return new Intl.NumberFormat(state.locale,{style:'currency',currency:code,maximumFractionDigits:['JPY','XOF'].includes(code)?0:2}).format(amount)}
function currencyName(code){try{return new Intl.DisplayNames([state.locale],{type:'currency'}).of(code)}catch{return code}}
function openModal(id){$('#'+id).classList.add('open')}
function closeModal(id){$('#'+id).classList.remove('open')}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),3000)}
async function request(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;let response;try{response=await fetch(API+path,{...options,headers})}catch{throw new Error(state.locale==='fr'?'Connexion impossible. Vérifiez votre réseau.':'Network unavailable.')};let data={};try{data=await response.json()}catch{}if(response.status===401&&state.token){localStorage.removeItem('resurface_token');state.token=null;showMarketing();openAuth('login')}if(!response.ok){const e=new Error(data.error||'Erreur');e.code=data.code;e.status=response.status;throw e}return data}


function isIos(){return /iphone|ipad|ipod/i.test(navigator.userAgent)||(/Macintosh/i.test(navigator.userAgent)&&navigator.maxTouchPoints>1)}
function isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true}
function pushCapability(){
  if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))return'unsupported';
  return Notification.permission;
}
function deviceInfo(){return{userAgent:navigator.userAgent,platform:navigator.userAgentData?.platform||navigator.platform||'',language:navigator.language||'',standalone:isStandalone()}}
function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4);const base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(char=>char.charCodeAt(0)))}
async function ensureServiceWorker(){if(state.swRegistration)return state.swRegistration;if(!('serviceWorker'in navigator))throw new Error(tr('push_unsupported'));state.swRegistration=await navigator.serviceWorker.register('/service-worker.js',{scope:'/'});await navigator.serviceWorker.ready;return state.swRegistration}
async function browserPushSubscription(){if(pushCapability()==='unsupported')return null;const registration=await ensureServiceWorker();return registration.pushManager.getSubscription()}
function pushStatusKey(){if(!state.config.push?.configured)return'notification_status_unconfigured';const capability=pushCapability();if(capability==='unsupported')return'notification_status_unsupported';if(capability==='denied')return'notification_status_denied';if(capability==='granted'&&state.pushStatus?.browserSubscribed)return'notification_status_enabled';return'notification_status_default'}
function updatePushUi(message=''){
  const key=pushStatusKey();const enabled=key==='notification_status_enabled';
  const badge=$('#pushStatusBadge');if(badge){badge.textContent=tr(key);badge.className='push-status '+(enabled?'enabled':key.includes('denied')?'denied':key.includes('unsupported')||key.includes('unconfigured')?'unsupported':'')}
  ['#settingsEnableNotifications','#enableNotificationsBtn'].forEach(sel=>{const el=$(sel);if(el)el.disabled=enabled||!state.config.push?.configured||pushCapability()==='unsupported'||pushCapability()==='denied'});
  $('#disableNotificationsBtn')?.classList.toggle('hidden',!enabled);
  $('#testNotificationBtn')?.toggleAttribute('disabled',!enabled);
  $('#iosPushInstructions')?.classList.toggle('hidden',!(isIos()&&!isStandalone()));
  const text=message||(!state.config.push?.configured?tr('push_server_unconfigured'):pushCapability()==='unsupported'?tr('push_unsupported'):pushCapability()==='denied'?tr('push_permission_denied'):enabled?tr('push_enabled'):'');
  if($('#pushSettingsMessage'))$('#pushSettingsMessage').textContent=text;
  if($('#notificationNudgeStatus'))$('#notificationNudgeStatus').textContent=text;
}
async function loadPushStatus(){
  if(!state.token)return;
  try{
    const server=await request('/push/status');
    let subscription=await browserPushSubscription().catch(()=>null);
    if(subscription&&server.configured){
      // Detect VAPID key rotation: if the server key changed, unsubscribe the old one and re-subscribe
      const serverPublicKey=state.config.push?.publicKey;
      if(serverPublicKey&&subscription.options?.applicationServerKey){
        const subKeyBytes=new Uint8Array(subscription.options.applicationServerKey);
        const serverKeyBytes=urlBase64ToUint8Array(serverPublicKey);
        const keysMismatch=subKeyBytes.length!==serverKeyBytes.length||!subKeyBytes.every((b,i)=>b===serverKeyBytes[i]);
        if(keysMismatch){
          try{await subscription.unsubscribe()}catch{}
          const registration=await ensureServiceWorker();
          subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:serverKeyBytes});
        }
      }
      try{await request('/push/subscribe',{method:'POST',body:JSON.stringify({subscription:subscription.toJSON(),deviceInfo:deviceInfo()})})}catch{}
    }
    state.pushStatus={...server,browserSubscribed:Boolean(subscription),endpoint:subscription?.endpoint||null};
  }catch(err){state.pushStatus={configured:false,browserSubscribed:false,error:err.message}}
  updatePushUi();
}
async function enableNotifications(){
  if(!state.token)return openAuth('login');
  if(!state.config.push?.configured){updatePushUi(tr('push_server_unconfigured'));return}
  if(isIos()&&!isStandalone()){$('#iosPushInstructions')?.classList.remove('hidden');updatePushUi();openModal('settingsOverlay');return}
  if(pushCapability()==='unsupported'){updatePushUi(tr('push_unsupported'));return}
  if(Notification.permission==='denied'){updatePushUi(tr('push_permission_denied'));return}
  const registration=await ensureServiceWorker();
  const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
  if(permission!=='granted'){await loadPushStatus();updatePushUi(tr('push_permission_denied'));return}
  let subscription=await registration.pushManager.getSubscription();
  if(!subscription){subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(state.config.push.publicKey)})}
  await request('/push/subscribe',{method:'POST',body:JSON.stringify({subscription:subscription.toJSON(),deviceInfo:deviceInfo()})});
  localStorage.setItem('resurface_push_enabled','1');
  $('#notificationNudge')?.classList.add('hidden');
  await loadPushStatus();updatePushUi(tr('push_enabled'));toast(tr('push_enabled'));
}
async function disableNotifications(){
  const subscription=await browserPushSubscription().catch(()=>null);
  if(subscription){try{await request('/push/unsubscribe',{method:'POST',body:JSON.stringify({endpoint:subscription.endpoint})})}catch{}await subscription.unsubscribe()}
  localStorage.removeItem('resurface_push_enabled');await loadPushStatus();updatePushUi(tr('push_disabled'));toast(tr('push_disabled'));
}
async function sendTestNotification(){
  const btn=$('#testNotificationBtn');btn.disabled=true;try{const result=await request('/push/test',{method:'POST',body:'{}'});const msg=result.sent?tr('push_test_sent'):tr('push_test_failed');updatePushUi(msg);toast(msg)}catch(err){updatePushUi(err.message||tr('push_test_failed'));toast(err.message||tr('push_test_failed'))}finally{btn.disabled=false}
}
function maybeOfferNotifications(afterFirstCreate=false){
  if(!afterFirstCreate||localStorage.getItem('resurface_push_nudge_dismissed')==='1')return;
  const capability=pushCapability();
  if(capability==='granted'&&state.pushStatus?.browserSubscribed)return;
  $('#notificationNudge')?.classList.remove('hidden');updatePushUi();
}
function dateTimePartsInZone(date,timeZone=state.settings?.timezone||deviceTimezone()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);return Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]))}
function prepareReminderInMinutes(minutes){const target=new Date(Math.ceil(Date.now()/60_000)*60_000+minutes*60_000);const p=dateTimePartsInZone(target);$('#customDate').value=`${p.year}-${p.month}-${p.day}`;$('#customTime').value=`${p.hour}:${p.minute}`;$('#itemText').focus();closeModal('settingsOverlay');toast(`${tr(minutes===1?'in_one_minute':'in_two_minutes')}`)}

function fillCurrencies(){const html=CURRENCIES.map(code=>`<option value="${code}">${code} — ${currencyName(code)}</option>`).join('');['#marketingCurrency','#currency','#settingsCurrency'].forEach(sel=>{const el=$(sel);if(!el)return;const value=el.value||currentCurrency();el.innerHTML=html;el.value=CURRENCIES.includes(value)?value:'EUR'})}
function fillCountries(){const el=$('#country');const current=state.settings?.country||detectedCountry()||'';el.innerHTML='<option value="">—</option>'+COUNTRY_OPTIONS.map(([c,n])=>`<option value="${c}">${n}</option>`).join('');el.value=current}
function fillTimezones(){const el=$('#timezone');let zones;try{zones=Intl.supportedValuesOf('timeZone')}catch{zones=['UTC','America/New_York','America/Sao_Paulo','Europe/Paris','Europe/London','Africa/Porto-Novo']};const current=state.settings?.timezone||deviceTimezone();if(!zones.includes(current))zones=[current,...zones];el.innerHTML=zones.map(z=>`<option value="${z}">${z.replaceAll('_',' ')}</option>`).join('');el.value=current;$('#deviceTimezone').textContent=`${tr('device_tz')}: ${deviceTimezone()}`}
function fillCategorySelect(id,value=''){const el=$(id);el.innerHTML=CATEGORY_DEFS.map(([v,k])=>`<option value="${v}">${tr(k)}</option>`).join('');el.value=CATEGORY_DEFS.some(([v])=>v===value)?value:'';updateCategoryHelp(id)}
function updateCategoryHelp(id){const el=$(id);const def=CATEGORY_DEFS.find(([v])=>v===el.value)||CATEGORY_DEFS[0];const target=id==='#category'?'#categoryHelp':'#editCategoryHelp';$(target).textContent=tr(def[2])}
function fillRecurrenceSelect(id,value='once'){const el=$(id);el.innerHTML=RECURRENCE_DEFS.map(([v,k])=>`<option value="${v}">${tr(k)}</option>`).join('');el.value=RECURRENCE_DEFS.some(([v])=>v===value)?value:'once';updateRecurrenceHelp(id)}
function updateRecurrenceHelp(id){const el=$(id);const def=RECURRENCE_DEFS.find(([v])=>v===el.value)||RECURRENCE_DEFS[0];const edit=id==='#editRecurring';$(edit?'#editRecurrenceHelp':'#recurrenceHelp').textContent=tr(def[2]);$(edit?'#editRecurrenceIntervalWrap':'#recurrenceIntervalWrap').classList.toggle('hidden',el.value!=='custom_days')}
function updatePrices(code=currentCurrency()){const price=`${formatPrice(code)} <small>${tr('per_month')}</small>`;$('#marketingPrice').innerHTML=price;$('#modalPrice').innerHTML=price;const ready=Boolean(state.config.currencies?.[code]?.checkoutEnabled);$('#currencyAvailability').textContent=tr(ready?'currency_ready':'currency_preview');$('#currencyAvailability').className='availability '+(ready?'available':'unavailable');$('#checkout').disabled=!ready;$('#checkout').title=ready?'':tr('currency_preview')}
function applyI18n(){document.documentElement.lang=state.locale;$$('[data-i18n]').forEach(el=>el.textContent=tr(el.dataset.i18n));$$('.locale-select').forEach(el=>el.value=state.locale);$('#itemText').placeholder=state.locale==='fr'?'Exemple : Relancer David dans deux semaines':'Example: Follow up with David in two weeks';fillCurrencies();fillCategorySelect('#category',$('#category')?.value||'');fillRecurrenceSelect('#recurring',$('#recurring')?.value||'once');if($('#editCategory').options.length)fillCategorySelect('#editCategory',$('#editCategory').value);if($('#editRecurring').options.length)fillRecurrenceSelect('#editRecurring',$('#editRecurring').value);updateAuthText();updatePrices($('#currency').value||currentCurrency());updateTimezoneHint();renderItems();updatePushUi()}
